from flask import Flask, Response, jsonify, request

app = Flask(__name__)
app.json.ensure_ascii = False

TASKS = {1: {"id": 1, "title": "Купить молоко", "done": False, "owner_id": 7}}
NEXT_ID = 2


def api_error(status, message, field=None):
    payload = {"error": {"status": status, "message": message}}
    if field is not None:
        payload["error"]["field"] = field
    return jsonify(payload), status


def serialize_task(task):
    return {
        "id": task["id"],
        "title": task["title"],
        "done": task["done"],
        "url": f"/api/v1/tasks/{task['id']}",
    }


@app.get("/api/v1/tasks")
def list_tasks():
    return jsonify({
        "items": [serialize_task(t) for t in TASKS.values()],
        "total": len(TASKS),
    })


@app.get("/api/v1/tasks/<int:task_id>")
def get_task(task_id):
    task = TASKS.get(task_id)
    if task is None:
        return api_error(404, "задача не найдена")
    return jsonify(serialize_task(task))


@app.post("/api/v1/tasks")
def create_task():
    global NEXT_ID
    data = request.get_json(silent=True)
    if data is None:
        return api_error(400, "ожидали JSON в теле запроса")
    title = data.get("title")
    if not isinstance(title, str) or not title.strip():
        return api_error(422, "заголовок не может быть пустым", field="title")
    task = {"id": NEXT_ID, "title": title.strip(), "done": False, "owner_id": 7}
    TASKS[NEXT_ID] = task
    NEXT_ID += 1
    response = jsonify(serialize_task(task))
    response.headers["Location"] = task["url"]
    return response, 201


@app.delete("/api/v1/tasks/<int:task_id>")
def delete_task(task_id):
    if TASKS.pop(task_id, None) is None:
        return api_error(404, "задача не найдена")
    return Response(status=204)


app.run(debug=True)

from flask import Flask, jsonify
from werkzeug.exceptions import HTTPException

app = Flask(__name__)


def api_error(status, message):
    return jsonify({"error": {"status": status, "message": message}}), status


@app.errorhandler(404)
def not_found(error):
    return api_error(404, "ресурс не найден")


@app.errorhandler(405)
def wrong_method(error):
    return api_error(405, "метод не поддерживается этим адресом")


@app.errorhandler(HTTPException)
def any_http_error(error):
    # ловит 400, 415 и всё остальное, что бросает сам Flask
    return api_error(error.code, error.description)


@app.errorhandler(Exception)
def unexpected(error):
    app.logger.exception("необработанная ошибка")
    return api_error(500, "внутренняя ошибка сервера")


app.run(debug=True)

